#  v
#Onboarding Draft Agent
#  |
#  v
#Pydantic Draft
#  |
#  v
#Deterministic Validation
#  |
#  v
#Human Preview / Approval
#  |
#  +--> baselines/<agent>.json
#  |
#  +--> registry/monitored_agents.json
#  |
#  v
#Guardian Live Monitor
